"""Verify generated bytes plus source-preservation and musical invariants."""
import collections
import hashlib
import json
import re
from pathlib import Path

import mido

from analyze_reference import PROJECT, REF, read_notes
from build_arrangement import BAR, CHORDS, END, HARMONY, SOURCE_MELODY, SOURCE_PIANO
from midi_creator.export import verify_export
from midi_creator.spec import compile_composition, load_json

OUT = PROJECT / 'v001'

def main():
    spec = load_json(OUT / '_internal/composition.json')
    compile_composition(spec, strict_timing=True)
    verified = verify_export(OUT)
    assert verified['ok'], verified
    actual = {}
    files = {}
    for layer in spec['layers']:
        path = OUT / 'MIDI' / (layer['id'] + '.mid')
        midi = mido.MidiFile(path)
        assert midi.type == 1 and len(midi.tracks) == 1 and midi.ticks_per_beat == 480
        ns, end = read_notes(midi.tracks[0])
        assert end == END and min(n['start_tick'] for n in ns) >= 4*BAR
        forbidden = {'sysex', 'program_change', 'key_signature', 'marker', 'text'}
        assert not any(m.type in forbidden or (m.type == 'control_change' and m.control in (0,32)) for m in midi.tracks[0])
        actual[layer['id']] = ns
        files[layer['id']] = dict(file=str(path.relative_to(OUT)), sha256=hashlib.sha256(path.read_bytes()).hexdigest(),
                                  notes=len(ns), tracks=1, end_tick=end, format=1)
    source_keys = collections.Counter((n['pitch'],n['start_tick']) for n in SOURCE_PIANO)
    output_keys = collections.Counter((n['pitch'],n['start_tick']) for n in actual['piano'])
    assert not (source_keys-output_keys)
    source_theme = [(n['pitch']-12,round(n['start_tick']/60)*60) for n in SOURCE_MELODY]
    output_theme = [(n['pitch'],n['start_tick']) for n in actual['strings-solo']]
    assert source_theme == output_theme
    for bar in range(4,76):
        first_bass = min((n for n in actual['precision-bass'] if bar*BAR <= n['start_tick'] < (bar+1)*BAR),key=lambda n:n['start_tick'])
        lowest_source = min(n['pitch'] for n in SOURCE_PIANO if n['start_tick']//BAR == bar)
        assert first_bass['pitch']%12 == lowest_source%12
        if bar >= 12:
            for tick in (bar*BAR + 20, bar*BAR + 960):
                sounding = {n['pitch']%12 for n in actual['strings-chord'] if n['start_tick'] <= tick < n['end_tick']}
                assert sounding == CHORDS[HARMONY[bar]]['pcs'], (bar+1,tick,sounding)
    for n in actual['flute-counter']:
        assert n['pitch']%12 in CHORDS[HARMONY[n['start_tick']//BAR]]['pcs']
        assert not any(s['start_tick'] < n['end_tick'] and s['end_tick'] > n['start_tick'] for s in actual['strings-solo'])
    analysis = json.loads((Path(__file__).parent/'reference-analysis.json').read_text(encoding='utf-8'))
    assert hashlib.sha256(REF.read_bytes()).hexdigest() == analysis['source_sha256']
    linked = []
    for readme in (OUT/'README.md',PROJECT/'README.md'):
        for relative in re.findall(r'\[[^\]]*\]\(([^)]+)\)',readme.read_text(encoding='utf-8')):
            assert (readme.parent/relative).is_file(), (readme,relative)
            linked.append(relative)
    receipt = dict(ok=True, validate_ok=True, export_verify_ok=True,
                   original_piano_pitch_onsets_preserved=445, source_melody_notes_preserved=71,
                   progression_and_slash_bass_preserved=True, source_sha256=analysis['source_sha256'],
                   initial_four_silent_bars_preserved=True, flute_rearranged=True,
                   flute_counter_notes=len(actual['flute-counter']), flute_plays_in_solo_rests=True,
                   files=files, readme_links_checked=linked,
                   plugin_loading_tested=False, cubase_import_tested=False, rendered=False, listened=False)
    (OUT/'_internal/delivery-receipt.json').write_text(json.dumps(receipt,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(json.dumps(receipt,ensure_ascii=False,indent=2))

if __name__ == '__main__':
    main()
